import{_ as s,o as a,c as e,a4 as l}from"./chunks/framework.DpieW3qv.js";const h=JSON.parse('{"title":"setup","description":"","frontmatter":{"title":"setup"},"headers":[],"relativePath":"cli/setup.md","filePath":"cli/setup.md","lastUpdated":null}'),t={name:"cli/setup.md"};function p(r,n,o,i,c,u){return a(),e("div",null,[...n[0]||(n[0]=[l(`<h1 id="setup" tabindex="-1">setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;setup&quot;">​</a></h1><p>View or change configuration (brand, data source, OCAPI). With no flags, <strong><code>make setup</code></strong> shows current config (or &quot;No configuration yet.&quot;) and offers <strong>View / Edit / Done</strong>. Edit runs the full wizard.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>make setup</code> is the full configuration wizard (brand, data source, OCAPI). For a quick brand change, use <strong><code>make switch</code></strong> to toggle loft ↔ ann (no args), or <strong><code>make switch BRAND=ann</code></strong> for a specific brand. Source and OCAPI still use <code>make setup</code>.</p><h2 id="view-first-menu-no-flags" tabindex="-1">View-first menu (no flags) <a class="header-anchor" href="#view-first-menu-no-flags" aria-label="Permalink to &quot;View-first menu (no flags)&quot;">​</a></h2><p>When you run <strong><code>make setup</code></strong> with no flags:</p><ol><li>Current configuration is shown (or &quot;No configuration yet.&quot;).</li><li>Menu: <strong>View current configuration</strong> / <strong>Edit configuration</strong> / <strong>Done</strong>.</li><li><strong>View</strong> — show config again, then return to the menu.</li><li><strong>Edit</strong> — run the full wizard (brand, source, OCAPI), then return to the menu.</li><li><strong>Done</strong> — exit.</li></ol><p>Flags <strong><code>--show</code></strong>, <strong><code>--brand</code></strong>, <strong><code>--source</code></strong>, <strong><code>--ocapi</code></strong> bypass the menu and behave as before.</p><h2 id="wizard-flow-edit-configuration" tabindex="-1">Wizard Flow (Edit configuration) <a class="header-anchor" href="#wizard-flow-edit-configuration" aria-label="Permalink to &quot;Wizard Flow (Edit configuration)&quot;">​</a></h2><p>Every step is pre-filled from your <code>.env</code>. Press Enter at each step to accept the default, or use arrow keys to change it. The wizard shows what was detected and where it came from, so you know exactly what each step does.</p><p>The full wizard (when you choose Edit, or on first run via <code>make status</code>) runs 4 steps:</p><ol><li><strong>Brand</strong> (Step 1 of 4) — <code>LOFT</code>, <code>Ann Taylor</code>, etc. Default is detected from <strong><code>SFCC_SITE_ID</code></strong>, <strong><code>SFCC_BRAND</code></strong>, or <strong><code>OCAPI_BRAND</code></strong> env (in that priority order). Context text shows which env var was used.</li><li><strong>OCAPI</strong> (Step 2 of 4) — Enable OCAPI sync? <strong>Yes</strong> (first/default) or No. Shows whether SFCC credentials are detected in env.</li><li><strong>Data source</strong> (Step 3 of 4) — <strong>Smartsheet</strong> (default when API key and sheet ID are both set in env) or Local Excel. Context text shows whether Smartsheet is ready.</li><li><strong>Sheet ID or Excel path</strong> (Step 4 of 4) — Branches based on the data source: <ul><li><strong>Smartsheet:</strong> Choose <strong>Use default (from env)</strong> or <strong>Enter manually</strong>. The API key is never prompted: <strong><code>SMARTSHEET_API_KEY</code></strong> must be set in the environment; if missing, setup shows a warning.</li><li><strong>Local:</strong> Prompts for the Excel file path (pre-filled with the standard location for the brand).</li></ul></li></ol><h3 id="example-loft-with-smartsheet-enter-through" tabindex="-1">Example: LOFT with Smartsheet (Enter through) <a class="header-anchor" href="#example-loft-with-smartsheet-enter-through" aria-label="Permalink to &quot;Example: LOFT with Smartsheet (Enter through)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>╔════════════════════════════════════════════════════════════╗</span></span>
<span class="line"><span>║           SFCC Campaign Automation — Setup                 ║</span></span>
<span class="line"><span>╠════════════════════════════════════════════════════════════╣</span></span>
<span class="line"><span>║  Your settings were detected from the .env file.           ║</span></span>
<span class="line"><span>║  Press Enter at each step to accept, or arrow to change.   ║</span></span>
<span class="line"><span>╚════════════════════════════════════════════════════════════╝</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 1 of 4 — Brand</span></span>
<span class="line"><span>  Detected LOFT from your SFCC_SITE_ID env variable.</span></span>
<span class="line"><span>  Change this if you work on a different brand (e.g. Ann Taylor).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Select brand  &gt; LOFT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓ Brand: LOFT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 2 of 4 — OCAPI Sync</span></span>
<span class="line"><span>  Pushes campaigns directly to SFCC. Your SFCC credentials are set.</span></span>
<span class="line"><span>  Disable this if you only want to preview campaigns locally.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Enable OCAPI sync?  &gt; Yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓ OCAPI: Enabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 3 of 4 — Data Source</span></span>
<span class="line"><span>  Smartsheet is ready (API key ✓, Sheet ID ✓ from env).</span></span>
<span class="line"><span>  Choose Local Excel if you want to load from a file on disk instead.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Data source  &gt; Smartsheet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓ Source: Smartsheet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 4 of 4 — Smartsheet Sheet ID</span></span>
<span class="line"><span>  Using 5846826791948164 from your SMARTSHEET_SHEET_ID_LOFT env variable.</span></span>
<span class="line"><span>  Choose &quot;Enter manually&quot; only if you need a different sheet.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Sheet ID  &gt; Use default (5846826791948164 from env)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓ Sheet ID: 5846826791948164 (from env)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br></div></div><h3 id="example-ann-taylor-with-local-excel" tabindex="-1">Example: Ann Taylor with Local Excel <a class="header-anchor" href="#example-ann-taylor-with-local-excel" aria-label="Permalink to &quot;Example: Ann Taylor with Local Excel&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Step 1 of 4 — Brand</span></span>
<span class="line"><span>  Detected Ann Taylor from your OCAPI_BRAND env variable.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Select brand  &gt; Ann Taylor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 3 of 4 — Data Source</span></span>
<span class="line"><span>  Choose where campaign data comes from.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Data source  &gt; Local Excel file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Step 4 of 4 — Local Excel File</span></span>
<span class="line"><span>  Path to the Excel file on disk.</span></span>
<span class="line"><span>  Default is the standard location for Ann Taylor.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>? Excel file path [docs/excel/Ann (Converted).xlsx]:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="config-file" tabindex="-1">Config File <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config File&quot;">​</a></h2><p>Writes <code>dev-env/.ocapi-config.json</code>.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>After setup completes, run <strong><code>make status</code></strong> or <strong><code>make pull</code></strong> to open the status hub.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/cli/pull.html"><code>pull</code></a></li><li><a href="/ocapi-docs.github.io/guides/env-and-auth.html">Environment Setup</a></li></ul>`,23)])])}const b=s(t,[["render",p]]);export{h as __pageData,b as default};
